SourceCode.Declaration:
/// <summary>
/// One store's journal of blind counts (Count types: One journal per store). Every blind count of
/// the store goes into the same D365FO counting journal until it is posted; the next blind count
/// then starts a new one. The figures are stored, kept current by
/// HSMobileOpsCountStoreJournalEngine::refreshTotals - display methods render blank on this
/// environment's forms. The Count control center lists one row per store journal.
/// </summary>
public class HSMobileOpsCountStoreJournal extends common
{
}

Method.Source:
public static HSMobileOpsCountStoreJournal find(RefRecId _recId, boolean _forUpdate = false)
{
    HSMobileOpsCountStoreJournal storeJournal;

    storeJournal.selectForUpdate(_forUpdate);
    if (_recId)
    {
        select firstonly storeJournal where storeJournal.RecId == _recId;
    }
    return storeJournal;
}

public static HSMobileOpsCountStoreJournal findByJournal(InventJournalId _journalId, boolean _forUpdate = false)
{
    HSMobileOpsCountStoreJournal storeJournal;

    storeJournal.selectForUpdate(_forUpdate);
    if (_journalId)
    {
        select firstonly storeJournal where storeJournal.JournalId == _journalId;
    }
    return storeJournal;
}
